const response = $input.first().json;
const status = Number(response.statusCode);
const body = response.body;
const base = { source: "https://api.github.com/repos/apb31/maintainerops", observed_at: new Date().toISOString() };
if (!Number.isInteger(status)) throw new Error("Missing HTTP status");
if (status !== 200) {
  return [{json: {...base, ok: false, status, retryable: status === 429 || status >= 500,
    reason: status === 403 ? "Access/rate-limit check required" : "Upstream non-success response"}}];
}
if (!body || typeof body !== "object" || Array.isArray(body) || body.full_name !== "apb31/maintainerops")
  throw new Error("Unexpected repository schema or identity");
for (const key of ["stargazers_count", "forks_count", "open_issues_count"])
  if (!Number.isSafeInteger(body[key]) || body[key] < 0) throw new Error("Invalid count: " + key);
return [{json: {...base, ok: true, repository: body.full_name, stars: body.stargazers_count,
  forks: body.forks_count, open_issues_and_prs: body.open_issues_count,
  note: "GitHub open_issues_count includes pull requests; not a count of issues alone."}}];
